def set_builtin_kinds(apps, schema_editor):
    """Existing binding prices keep their meaning: staple/spiral/thermal/beads are their own kind."""

    Price = apps.get_model("printing", "PrintBindingPrice")
    for kind in ("staple", "spiral", "thermal", "beads"):
        Price.objects.filter(binding=kind, kind="other").update(kind=kind)


